{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "전통시장 영수증으로 공영주차장 할인이 적용되지 않는 이유",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "전통시장 또는 상권활성화구역에서 구매한 영수증 제시 또는 구매 사실이 주차시간측정계기를 통해 확인된 차량이 공영주차장을 이용하면 최초 2시간까지 주차요금의 100분의 50을 할인한다. 다만, 1급지에 소재한 주차장을 이용할 경우에는 주차요금을 감면하지 아니한다.",
          "b_ids": "주차장:제7조제1항제8호, 주차장:제7조제1항제8호단서"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "공영주차장 안내판의 1급지 표기와 전통시장 영수증 할인 관계",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "1급지에 소재한 주차장을 이용할 경우에는 전통시장 영수증 할인(주차요금의 100분의 50)을 감면하지 아니한다. 따라서 안내판에 1급지라고 쓰여 있으면 그 주차장은 전통시장 영수증 할인 적용 대상에서 제외된다.",
          "b_ids": "주차장:제7조제1항제8호단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
